1	package indexroom
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// filteredStatsChain builds the shared fixture for QueryTimeStats TxIDs
9	// filtering regressions:
10	//
11	//	height 1, time  0: ["a", "a", "", "A", " a "]
12	//	height 2, time 10: ["", "a"]
13	//	height 3, no time: ["a", "", "zzz"]
14	//	height 4, time 20: ["x"]
15	//
16	// Over window [0,20) step 10, height 1 lands in bucket [0,10) and height 2
17	// in [10,20); height 3 has no timestamp and must only surface in
18	// MissingTimeBlocks even though it carries matching identifiers; height 4's
19	// timestamp equals the excluded window end. The fixture deliberately keeps
20	// case ("a" vs "A"), surrounding whitespace (" a "), the empty identifier,
21	// and a repeated in-block identifier side by side.
22	func filteredStatsChain(t *testing.T) *Index {
23		t.Helper()
24		index := New()
25		blocks := []Block{
26			timeBlock(1, "h1", "g", []string{"a", "a", "", "A", " a "}, intptr(0)),
27			timeBlock(2, "h2", "h1", []string{"", "a"}, intptr(10)),
28			timeBlock(3, "h3", "h2", []string{"a", "", "zzz"}, nil),
29			timeBlock(4, "h4", "h3", []string{"x"}, intptr(20)),
30		}
31		for _, b := range blocks {
32			if err := index.Append(b); err != nil {
33				t.Fatalf("setup append at %d: %v", b.Height, err)
34			}
35		}
36		return index
37	}
38	
39	func filteredStatsQuery(txIDs []string) TimeStatsQuery {
40		return TimeStatsQuery{TxIDs: txIDs, Start: 0, End: 20, StepSeconds: 10}
41	}
42	
43	// TestQueryTimeStatsNilEmptyAndSoleEmptyStringFilter pins the three ways to
44	// supply TxIDs: a nil list and an empty list both count every transaction,
45	// including empty identifiers; the one-element list [""] counts only
46	// empty-identifier transactions.
47	func TestQueryTimeStatsNilEmptyAndSoleEmptyStringFilter(t *testing.T) {
48		index := filteredStatsChain(t)
49	
50		// No identifier given and an explicitly empty list are the same
51		// unrestricted query: every occurrence counts, the empty identifier in
52		// both timed blocks included.
53		allWant := TimeStats{
54			Buckets: []TimeBucket{
55				{Start: 0, End: 10, TxCount: 5, DistinctTxIDs: 4, Blocks: 1},
56				{Start: 10, End: 20, TxCount: 2, DistinctTxIDs: 2, Blocks: 1},
57			},
58			Totals:            TimeTotals{TxCount: 7, DistinctTxIDs: 4, Blocks: 2},
59			FromHeight:        1,
60			ToHeight:          4,
61			MissingTimeBlocks: 1,
62		}
63		for name, txIDs := range map[string][]string{
64			"nil TxIDs":   nil,
65			"empty TxIDs": {},
66		} {
67			t.Run(name, func(t *testing.T) {
68				got, err := index.QueryTimeStats(filteredStatsQuery(txIDs))
69				if err != nil {
70					t.Fatal(err)
71				}
72				if !reflect.DeepEqual(got, allWant) {
73					t.Fatalf("stats=%+v\nwant=%+v", got, allWant)
74				}
75			})
76		}
77	
78		// [""] is a real filter matching only the empty identifier, exactly once
79		// in each timed block: one occurrence, one distinct id, one block per
80		// bucket; two occurrences but still one distinct id over the window.
81		got, err := index.QueryTimeStats(filteredStatsQuery([]string{""}))
82		if err != nil {
83			t.Fatal(err)
84		}
85		emptyWant := TimeStats{
86			Buckets: []TimeBucket{
87				{Start: 0, End: 10, TxCount: 1, DistinctTxIDs: 1, Blocks: 1},
88				{Start: 10, End: 20, TxCount: 1, DistinctTxIDs: 1, Blocks: 1},
89			},
90			Totals:            TimeTotals{TxCount: 2, DistinctTxIDs: 1, Blocks: 2},
91			FromHeight:        1,
92			ToHeight:          4,
93			MissingTimeBlocks: 1,
94		}
95		if !reflect.DeepEqual(got, emptyWant) {
96			t.Fatalf("stats=%+v\nwant=%+v", got, emptyWant)
97		}
98	}
99	
100	// TestQueryTimeStatsFilterExactStringComparison pins exact-string semantics on
101	// the returned counters: case, leading/trailing whitespace, and string
102	// boundaries all matter.
103	func TestQueryTimeStatsFilterExactStringComparison(t *testing.T) {
104		index := New()
105		blocks := []Block{
106			timeBlock(1, "h1", "g", []string{"a", "A", " a ", "a ", " a", "ab", "a"}, intptr(0)),
107			timeBlock(2, "h2", "h1", []string{"a", "ab"}, intptr(5)),
108		}
109		for _, b := range blocks {
110			if err := index.Append(b); err != nil {
111				t.Fatal(err)
112			}
113		}
114		query := TimeStatsQuery{Start: 0, End: 10, StepSeconds: 10}
115	
116		// Each spelling matches only its own occurrences; "a" appears twice in
117		// block 1 and once in block 2, and "ab" must never be swallowed by "a".
118		cases := []struct {
119			name     string
120			txIDs    []string
121			txCount  int64
122			distinct int64
123			blocks   int64
124		}{
125			{"lowercase a", []string{"a"}, 3, 1, 2},
126			{"uppercase A", []string{"A"}, 1, 1, 1},
127			{"padded a", []string{" a "}, 1, 1, 1},
128			{"trailing space", []string{"a "}, 1, 1, 1},
129			{"leading space", []string{" a"}, 1, 1, 1},
130			{"boundary ab", []string{"ab"}, 2, 1, 2},
131			{"whitespace is not empty", []string{" "}, 0, 0, 0},
132		}
133		for _, tc := range cases {
134			t.Run(tc.name, func(t *testing.T) {
135				query.TxIDs = tc.txIDs
136				got, err := index.QueryTimeStats(query)
137				if err != nil {
138					t.Fatal(err)
139				}
140				b := got.Buckets[0]
141				if b.TxCount != tc.txCount || b.DistinctTxIDs != tc.distinct || b.Blocks != tc.blocks {
142					t.Fatalf("filter %q bucket=%+v, want tx=%d distinct=%d blocks=%d",
143						tc.txIDs, b, tc.txCount, tc.distinct, tc.blocks)
144				}
145				if got.Totals != (TimeTotals{TxCount: tc.txCount, DistinctTxIDs: tc.distinct, Blocks: tc.blocks}) {
146					t.Fatalf("filter %q totals=%+v", tc.txIDs, got.Totals)
147				}
148			})
149		}
150	
151		// The three easily-confused spellings are three distinct window ids,
152		// never merged by case folding or trimming.
153		query.TxIDs = []string{"a", "A", " a "}
154		got, err := index.QueryTimeStats(query)
155		if err != nil {
156			t.Fatal(err)
157		}
158		if got.Totals.DistinctTxIDs != 3 || got.Totals.TxCount != 5 {
159			t.Fatalf("distinct spellings merged: totals=%+v", got.Totals)
160		}
161	}
162	
163	// TestQueryTimeStatsFilterOrderAndDuplicatesEquivalent pins that reordering or
164	// repeating filter members changes neither per-bucket nor whole-window
165	// counters, while the caller's slice keeps its exact contents and order.
166	func TestQueryTimeStatsFilterOrderAndDuplicatesEquivalent(t *testing.T) {
167		index := filteredStatsChain(t)
168	
169		spellings := [][]string{
170			{"a", ""},
171			{"", "a"},
172			{"", "a", "a"},
173			{"a", "", "a", "", "a"},
174			{"a", "a", "", ""},
175		}
176		want := TimeStats{
177			Buckets: []TimeBucket{
178				// Height 1: "a", "a", "" match -> 3 occurrences, 2 ids, 1 block.
179				{Start: 0, End: 10, TxCount: 3, DistinctTxIDs: 2, Blocks: 1},
180				// Height 2: "" and "a" match -> 2 occurrences, 2 ids, 1 block.
181				{Start: 10, End: 20, TxCount: 2, DistinctTxIDs: 2, Blocks: 1},
182			},
183			// 5 occurrences over the window but only the two ids "a" and "".
184			Totals:            TimeTotals{TxCount: 5, DistinctTxIDs: 2, Blocks: 2},
185			FromHeight:        1,
186			ToHeight:          4,
187			MissingTimeBlocks: 1,
188		}
189		for _, in := range spellings {
190			saved := append([]string{}, in...)
191			got, err := index.QueryTimeStats(filteredStatsQuery(in))
192			if err != nil {
193				t.Fatalf("filter %q: %v", in, err)
194			}
195			if !reflect.DeepEqual(got, want) {
196				t.Fatalf("filter %q stats=%+v\nwant=%+v", in, got, want)
197			}
198			if !reflect.DeepEqual(in, saved) {
199				t.Fatalf("caller list mutated: got %q, want %q", in, saved)
200			}
201		}
202	
203		// Repeating the sole member is equivalent to the one-member set.
204		single, err := index.QueryTimeStats(filteredStatsQuery([]string{"a"}))
205		if err != nil {
206			t.Fatal(err)
207		}
208		repeated, err := index.QueryTimeStats(filteredStatsQuery([]string{"a", "a", "a"}))
209		if err != nil {
210			t.Fatal(err)
211		}
212		if !reflect.DeepEqual(single, repeated) {
213			t.Fatalf("[a] and [a,a,a] differ:\n%+v\n%+v", single, repeated)
214		}
215		singleWant := TimeStats{
216			Buckets: []TimeBucket{
217				{Start: 0, End: 10, TxCount: 2, DistinctTxIDs: 1, Blocks: 1},
218				{Start: 10, End: 20, TxCount: 1, DistinctTxIDs: 1, Blocks: 1},
219			},
220			Totals:            TimeTotals{TxCount: 3, DistinctTxIDs: 1, Blocks: 2},
221			FromHeight:        1,
222			ToHeight:          4,
223			MissingTimeBlocks: 1,
224		}
225		if !reflect.DeepEqual(single, singleWant) {
226			t.Fatalf("single-id stats=%+v\nwant=%+v", single, singleWant)
227		}
228	}
229	
230	// TestQueryTimeStatsDuplicateOccurrencesBlockOnceAndDistinctDedup is the
231	// canonical counting scenario: repeated identifiers inside one block count by
232	// occurrence for TxCount, a matching block counts once, and distinct ids are
233	// deduplicated both inside a segment (across blocks) and over the window.
234	func TestQueryTimeStatsDuplicateOccurrencesBlockOnceAndDistinctDedup(t *testing.T) {
235		// Two blocks in the same segment share identifiers: occurrences and
236		// blocks both rise, but the per-segment distinct count stays deduplicated.
237		index := New()
238		blocks := []Block{
239			timeBlock(1, "h1", "g", []string{"a", "b", "a"}, intptr(0)),
240			timeBlock(2, "h2", "h1", []string{"b", "b", "a"}, intptr(5)),
241			timeBlock(3, "h3", "h2", []string{"a"}, intptr(10)),
242		}
243		for _, b := range blocks {
244			if err := index.Append(b); err != nil {
245				t.Fatal(err)
246			}
247		}
248		got, err := index.QueryTimeStats(TimeStatsQuery{
249			TxIDs: []string{"a", "b", "a"}, Start: 0, End: 20, StepSeconds: 10,
250		})
251		if err != nil {
252			t.Fatal(err)
253		}
254		want := TimeStats{
255			Buckets: []TimeBucket{
256				// Segment [0,10): 3+3=6 occurrences over 2 blocks, 2 distinct ids.
257				{Start: 0, End: 10, TxCount: 6, DistinctTxIDs: 2, Blocks: 2},
258				{Start: 10, End: 20, TxCount: 1, DistinctTxIDs: 1, Blocks: 1},
259			},
260			// "a" and "b" both recur across segments, so window distinct is 2,
261			// not the per-bucket sum of 3.
262			Totals:     TimeTotals{TxCount: 7, DistinctTxIDs: 2, Blocks: 3},
263			FromHeight: 1,
264			ToHeight:   3,
265		}
266		if !reflect.DeepEqual(got, want) {
267			t.Fatalf("stats=%+v\nwant=%+v", got, want)
268		}
269	
270		// The task's worked example verbatim: filter [""] over the two-block
271		// fixture gives one occurrence / one id / one block per segment and two
272		// occurrences / one id / two blocks over the window; ["a",""] (in either
273		// order, with or without repeats) gives 3 and 2 occurrences and two
274		// distinct window ids.
275		example := filteredStatsChain(t)
276		emptyOnly, err := example.QueryTimeStats(filteredStatsQuery([]string{""}))
277		if err != nil {
278			t.Fatal(err)
279		}
280		if emptyOnly.Buckets[0] != (TimeBucket{Start: 0, End: 10, TxCount: 1, DistinctTxIDs: 1, Blocks: 1}) ||
281			emptyOnly.Buckets[1] != (TimeBucket{Start: 10, End: 20, TxCount: 1, DistinctTxIDs: 1, Blocks: 1}) {
282			t.Fatalf("[\"\"] buckets=%+v", emptyOnly.Buckets)
283		}
284		if emptyOnly.Totals != (TimeTotals{TxCount: 2, DistinctTxIDs: 1, Blocks: 2}) {
285			t.Fatalf("[\"\"] totals=%+v", emptyOnly.Totals)
286		}
287		for _, txIDs := range [][]string{{"a", ""}, {"", "a", "a"}} {
288			stats, err := example.QueryTimeStats(filteredStatsQuery(txIDs))
289			if err != nil {
290				t.Fatal(err)
291			}
292			if stats.Buckets[0].TxCount != 3 || stats.Buckets[1].TxCount != 2 {
293				t.Fatalf("filter %q tx counts=%d,%d, want 3,2", txIDs, stats.Buckets[0].TxCount, stats.Buckets[1].TxCount)
294			}
295			if stats.Totals.DistinctTxIDs != 2 {
296				t.Fatalf("filter %q window distinct=%d, want 2", txIDs, stats.Totals.DistinctTxIDs)
297			}
298		}
299	}
300	
301	// TestQueryTimeStatsMissingTimeBlocksUnchangedByFilter pins that blocks
302	// without a timestamp stay out of every bucket (even when they hold matching
303	// transactions) while MissingTimeBlocks is counted over the resolved height
304	// range regardless of the filter.
305	func TestQueryTimeStatsMissingTimeBlocksUnchangedByFilter(t *testing.T) {
306		// Height 3 lacks a time yet holds matches for every filter below.
307		index := filteredStatsChain(t)
308	
309		for name, txIDs := range map[string][]string{
310			"unrestricted":   nil,
311			"empty id":       {""},
312			"a and empty":    {"a", ""},
313			"no chain match": {"zzz"},
314		} {
315			t.Run(name, func(t *testing.T) {
316				got, err := index.QueryTimeStats(filteredStatsQuery(txIDs))
317				if err != nil {
318					t.Fatal(err)
319				}
320				if got.MissingTimeBlocks != 1 {
321					t.Fatalf("MissingTimeBlocks=%d, want 1", got.MissingTimeBlocks)
322				}
323				// The untimed block must never contribute a block to a bucket,
324				// including for filters it matches.
325				for i, b := range got.Buckets {
326					if b.Blocks > 1 {
327						t.Fatalf("bucket %d counted the untimed block: %+v", i, b)
328					}
329				}
330				if got.Totals.Blocks > 2 {
331					t.Fatalf("window totals counted the untimed block: %+v", got.Totals)
332				}
333			})
334		}
335	
336		// Restricting the height range to the untimed block alone still reports
337		// it as missing, while no segment receives anything.
338		ranged, err := index.QueryTimeStats(TimeStatsQuery{
339			From: 3, To: 3, TxIDs: []string{"a", ""}, Start: 0, End: 20, StepSeconds: 10,
340		})
341		if err != nil {
342			t.Fatal(err)
343		}
344		if ranged.FromHeight != 3 || ranged.ToHeight != 3 || ranged.MissingTimeBlocks != 1 {
345			t.Fatalf("ranged resolution/missing=%+v", ranged)
346		}
347		for i, b := range ranged.Buckets {
348			if b != (TimeBucket{Start: b.Start, End: b.End}) {
349				t.Fatalf("bucket %d carries data from an untimed block: %+v", i, b)
350			}
351		}
352		if ranged.Totals != (TimeTotals{}) {
353			t.Fatalf("totals=%+v, want zero", ranged.Totals)
354		}
355	}
356	
357	// TestQueryTimeStatsNoMatchReturnsFullZeroedWindow pins that a filter with no
358	// match on chain is a successful query: buckets still cover the whole
359	// requested window (including a truncated final segment) with every counter
360	// at zero, while MissingTimeBlocks follows the selected height range.
361	func TestQueryTimeStatsNoMatchReturnsFullZeroedWindow(t *testing.T) {
362		index := filteredStatsChain(t)
363	
364		got, err := index.QueryTimeStats(TimeStatsQuery{
365			TxIDs: []string{"zzz"}, Start: 0, End: 20, StepSeconds: 10,
366		})
367		if err != nil {
368			t.Fatalf("no-match query failed: %v", err)
369		}
370		if got.FromHeight != 1 || got.ToHeight != 4 || got.MissingTimeBlocks != 1 {
371			t.Fatalf("resolved range/missing=%+v", got)
372		}
373		wantBounds := [][2]int64{{0, 10}, {10, 20}}
374		if len(got.Buckets) != len(wantBounds) {
375			t.Fatalf("buckets=%d, want %d", len(got.Buckets), len(wantBounds))
376		}
377		for i, b := range got.Buckets {
378			if b.Start != wantBounds[i][0] || b.End != wantBounds[i][1] {
379				t.Fatalf("bucket %d bounds=[%d,%d), want [%d,%d)",
380					i, b.Start, b.End, wantBounds[i][0], wantBounds[i][1])
381			}
382			if b.TxCount != 0 || b.DistinctTxIDs != 0 || b.Blocks != 0 {
383				t.Fatalf("bucket %d non-zero without matches: %+v", i, b)
384			}
385		}
386		if got.Totals != (TimeTotals{}) {
387			t.Fatalf("totals=%+v, want zero", got.Totals)
388		}
389	
390		// Full coverage persists with a truncated final bucket and a height
391		// range that starts on the untimed block; height 4 at time 20 sits in
392		// the last segment but its "x" does not match, so it stays zero.
393		truncated, err := index.QueryTimeStats(TimeStatsQuery{
394			TxIDs: []string{"zzz"}, From: 2, Start: 0, End: 25, StepSeconds: 10,
395		})
396		if err != nil {
397			t.Fatal(err)
398		}
399		truncBounds := [][2]int64{{0, 10}, {10, 20}, {20, 25}}
400		if len(truncated.Buckets) != 3 {
401			t.Fatalf("buckets=%d, want 3", len(truncated.Buckets))
402		}
403		for i, b := range truncated.Buckets {
404			if b.Start != truncBounds[i][0] || b.End != truncBounds[i][1] {
405				t.Fatalf("bucket %d bounds=[%d,%d), want [%d,%d)",
406					i, b.Start, b.End, truncBounds[i][0], truncBounds[i][1])
407			}
408			if b.TxCount != 0 || b.DistinctTxIDs != 0 || b.Blocks != 0 {
409				t.Fatalf("bucket %d non-zero: %+v", i, b)
410			}
411		}
412		if truncated.Totals != (TimeTotals{}) {
413			t.Fatalf("totals=%+v, want zero", truncated.Totals)
414		}
415		if truncated.FromHeight != 2 || truncated.ToHeight != 4 || truncated.MissingTimeBlocks != 1 {
416			t.Fatalf("resolved range/missing=%+v", truncated)
417		}
418	
419		// A multi-member filter where nothing exists on chain at all.
420		none, err := index.QueryTimeStats(TimeStatsQuery{
421			TxIDs: []string{"nope", "nada", ""}, Start: 0, End: 20, StepSeconds: 10,
422		})
423		if err != nil {
424			t.Fatal(err)
425		}
426		// The empty id DOES exist, so this filter matches the two empty-id
427		// occurrences; a truly absent set must not include "".
428		if none.Totals.TxCount != 2 {
429			t.Fatalf("filter containing \"\" must match empty ids: totals=%+v", none.Totals)
430		}
431		absent, err := index.QueryTimeStats(TimeStatsQuery{
432			TxIDs: []string{"nope", "nada"}, Start: 0, End: 20, StepSeconds: 10,
433		})
434		if err != nil {
435			t.Fatal(err)
436		}
437		if absent.Totals != (TimeTotals{}) || absent.MissingTimeBlocks != 1 {
438			t.Fatalf("absent filter result=%+v", absent)
439		}
440	}
