1	package indexroom
2	
3	import (
4		"fmt"
5		"reflect"
6		"testing"
7	)
8	
9	// consistencyChain builds the shared fixture chain for the
10	// QueryTxs/QueryTimeStats consistency regression tests:
11	//
12	//	height 1: [a, b, a]      t=100  — one identifier twice in one block
13	//	height 2: [A, " a", "a "] t=95  — case/whitespace variants, time decreases with height
14	//	height 3: [b]            no timestamp
15	//	height 4: [a, c]         t=0    — a real zero timestamp
16	//	height 5: [c, c, ""]     t=109  — repeated identifier and an empty identifier
17	//	height 6: [b, a]         t=110  — sits at the excluded end of the usual window
18	//	height 7: [d]            t=105
19	func consistencyChain(t *testing.T) *Index {
20		t.Helper()
21		index := New()
22		blocks := []struct {
23			txs  []string
24			time *int64
25		}{
26			{[]string{"a", "b", "a"}, intptr(100)},
27			{[]string{"A", " a", "a "}, intptr(95)},
28			{[]string{"b"}, nil},
29			{[]string{"a", "c"}, intptr(0)},
30			{[]string{"c", "c", ""}, intptr(109)},
31			{[]string{"b", "a"}, intptr(110)},
32			{[]string{"d"}, intptr(105)},
33		}
34		for i, entry := range blocks {
35			height := int64(i + 1)
36			parent := "genesis"
37			if height > 1 {
38				parent = fmt.Sprintf("h%d", height-1)
39			}
40			block := Block{
41				Height: height,
42				Hash:   fmt.Sprintf("h%d", height),
43				Parent: parent,
44				Txs:    entry.txs,
45				Time:   entry.time,
46			}
47			if err := index.Append(block); err != nil {
48				t.Fatalf("setup append at %d: %v", height, err)
49			}
50		}
51		return index
52	}
53	
54	// oracleScan recomputes the expected matching occurrences straight from the
55	// blocks stored in the index, without going through QueryTxs or
56	// QueryTimeStats, so a bug that makes both queries miss the same data still
57	// fails the test. The height range follows query semantics: a zero from
58	// means height 1, a zero to means the current tip. A nil window disables
59	// time filtering. It also reports how many blocks inside the resolved range
60	// carry no timestamp, mirroring TimeStats.MissingTimeBlocks.
61	func oracleScan(index *Index, from, to int64, txIDs []string, window *timeWindow) (hits []TxHit, missingTime int64) {
62		if from == 0 {
63			from = 1
64		}
65		if to == 0 || to > index.Tip {
66			to = index.Tip
67		}
68		var set map[string]bool
69		if len(txIDs) > 0 {
70			set = make(map[string]bool, len(txIDs))
71			for _, id := range txIDs {
72				set[id] = true
73			}
74		}
75		for height := from; height <= to; height++ {
76			block := index.Blocks[height]
77			if block.Time == nil {
78				missingTime++
79				if window != nil && window.enabled {
80					// No timestamp: never matches an enabled window.
81					continue
82				}
83			} else if window != nil && window.enabled && (*block.Time < window.start || *block.Time >= window.end) {
84				continue
85			}
86			for position, tx := range block.Txs {
87				if set != nil && !set[tx] {
88					continue
89				}
90				hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
91			}
92		}
93		return hits, missingTime
94	}
95	
96	// summarizeHits counts the distinct blocks and distinct identifiers among
97	// the occurrences; every occurrence counts toward the total, so an
98	// identifier repeated inside one block raises the total but not the block
99	// count, and one recurring across blocks raises the window distinct count
100	// only once.
101	func summarizeHits(hits []TxHit) (blocks, distinct int64) {
102		heightSet := make(map[int64]struct{})
103		idSet := make(map[string]struct{})
104		for _, hit := range hits {
105			heightSet[hit.Height] = struct{}{}
106			idSet[hit.TxID] = struct{}{}
107		}
108		return int64(len(heightSet)), int64(len(idSet))
109	}
110	
111	// oracleBuckets distributes the windowed occurrences over the segments
112	// [start, start+step), ... cut off at end, computing every count from the
113	// stored block timestamps. The final segment may be narrower than step.
114	func oracleBuckets(index *Index, hits []TxHit, start, end, step int64) []TimeBucket {
115		var buckets []TimeBucket
116		for bStart := start; bStart < end; bStart += step {
117			bEnd := bStart + step
118			if bEnd > end {
119				bEnd = end
120			}
121			buckets = append(buckets, TimeBucket{Start: bStart, End: bEnd})
122		}
123		distinct := make([]map[string]struct{}, len(buckets))
124		blockSets := make([]map[int64]struct{}, len(buckets))
125		for _, hit := range hits {
126			when := index.Blocks[hit.Height].Time
127			if when == nil {
128				continue
129			}
130			i := (*when - start) / step
131			buckets[i].TxCount++
132			if distinct[i] == nil {
133				distinct[i] = make(map[string]struct{})
134				blockSets[i] = make(map[int64]struct{})
135			}
136			distinct[i][hit.TxID] = struct{}{}
137			blockSets[i][hit.Height] = struct{}{}
138		}
139		for i := range buckets {
140			buckets[i].DistinctTxIDs = int64(len(distinct[i]))
141			buckets[i].Blocks = int64(len(blockSets[i]))
142		}
143		return buckets
144	}
145	
146	// flattenHits concatenates the hits of every page in order.
147	func flattenHits(pages []TxPage) []TxHit {
148		var hits []TxHit
149		for _, page := range pages {
150			hits = append(hits, page.Hits...)
151		}
152		return hits
153	}
154	
155	// reversed returns the occurrences in the exact opposite order, the expected
156	// descending read of the same pinned range: heights and positions decrease,
157	// while each hit keeps its original block position.
158	func reversed(hits []TxHit) []TxHit {
159		if hits == nil {
160			return nil
161		}
162		out := make([]TxHit, len(hits))
163		for i, hit := range hits {
164			out[len(hits)-1-i] = hit
165		}
166		return out
167	}
168	
169	// collectPagesResizing reads the whole query like collectPages but rotates
170	// through the given page sizes, so continuations exercise changing page
171	// lengths inside one pinned query.
172	func collectPagesResizing(t *testing.T, index *Index, query TxQuery, sizes []int) []TxPage {
173		t.Helper()
174		var pages []TxPage
175		for i := 0; ; i++ {
176			query.PageSize = sizes[i%len(sizes)]
177			page, err := index.QueryTxs(query)
178			if err != nil {
179				t.Fatalf("query page %d failed: %v", i, err)
180			}
181			pages = append(pages, page)
182			if page.NextCursor == "" {
183				return pages
184			}
185			query.Cursor = page.NextCursor
186		}
187	}
188	
189	// assertConsistent pins one combination of height range, identifier set and
190	// time window, then checks that QueryTimeStats and the fully paginated
191	// QueryTxs agree with each other and with an independent recomputation from
192	// the stored blocks. Both read directions and rotated page sizes are
193	// exercised, and every stats bucket is cross-checked against a detail query
194	// over exactly its own sub-window.
195	func assertConsistent(t *testing.T, index *Index, from, to int64, txIDs []string, start, end, step int64) {
196		t.Helper()
197	
198		window := &timeWindow{enabled: true, start: start, end: end}
199		wantHits, wantMissing := oracleScan(index, from, to, txIDs, window)
200		wantBlocks, wantDistinct := summarizeHits(wantHits)
201		wantBuckets := oracleBuckets(index, wantHits, start, end, step)
202	
203		resolvedFrom := from
204		if resolvedFrom == 0 {
205			resolvedFrom = 1
206		}
207		resolvedTo := to
208		if resolvedTo == 0 || resolvedTo > index.Tip {
209			resolvedTo = index.Tip
210		}
211	
212		// The statistics answer must match the oracle exactly: bucket bounds
213		// cover the whole window, per-bucket counts come from the stored
214		// blocks, totals deduplicate over the whole window, and missing-time
215		// blocks are counted over the resolved height range.
216		stats, err := index.QueryTimeStats(TimeStatsQuery{
217			From: from, To: to, TxIDs: txIDs,
218			Start: start, End: end, StepSeconds: step,
219		})
220		if err != nil {
221			t.Fatalf("QueryTimeStats failed: %v", err)
222		}
223		if !reflect.DeepEqual(stats.Buckets, wantBuckets) {
224			t.Fatalf("buckets=%+v, want %+v", stats.Buckets, wantBuckets)
225		}
226		wantTotals := TimeTotals{TxCount: int64(len(wantHits)), DistinctTxIDs: wantDistinct, Blocks: wantBlocks}
227		if stats.Totals != wantTotals {
228			t.Fatalf("totals=%+v, want %+v", stats.Totals, wantTotals)
229		}
230		if stats.FromHeight != resolvedFrom || stats.ToHeight != resolvedTo {
231			t.Fatalf("resolved heights=[%d,%d], want [%d,%d]",
232				stats.FromHeight, stats.ToHeight, resolvedFrom, resolvedTo)
233		}
234		if stats.MissingTimeBlocks != wantMissing {
235			t.Fatalf("missing time blocks=%d, want %d", stats.MissingTimeBlocks, wantMissing)
236		}
237		// Occurrence and block totals are the sums of the bucket values (one
238		// occurrence lands in exactly one bucket); the distinct total is the
239		// window-wide dedup and may be smaller than the bucket sum.
240		var sumTx, sumBlocks, sumDistinct int64
241		for _, bucket := range stats.Buckets {
242			sumTx += bucket.TxCount
243			sumBlocks += bucket.Blocks
244			sumDistinct += bucket.DistinctTxIDs
245		}
246		if sumTx != stats.Totals.TxCount || sumBlocks != stats.Totals.Blocks {
247			t.Fatalf("bucket sums tx=%d blocks=%d, totals=%+v", sumTx, sumBlocks, stats.Totals)
248		}
249		if sumDistinct < stats.Totals.DistinctTxIDs {
250			t.Fatalf("bucket distinct sum %d below window distinct %d", sumDistinct, stats.Totals.DistinctTxIDs)
251		}
252	
253		// The paginated detail read, ascending with a rotating page size, must
254		// produce exactly the oracle occurrences; every page must report the
255		// whole-range totals, not just its own slice.
256		base := TxQuery{From: from, To: to, TxIDs: txIDs, TimeStart: &start, TimeEnd: &end}
257		pages := collectPagesResizing(t, index, base, []int{1, 3, 2, 5})
258		if got := flattenHits(pages); !reflect.DeepEqual(got, wantHits) {
259			t.Fatalf("ascending hits=%v, want %v", got, wantHits)
260		}
261		for i, page := range pages {
262			if page.TotalMatches != int64(len(wantHits)) || page.MatchedBlocks != wantBlocks {
263				t.Fatalf("page %d stats total=%d blocks=%d, want %d/%d",
264					i, page.TotalMatches, page.MatchedBlocks, len(wantHits), wantBlocks)
265			}
266			if page.ToHeight != resolvedTo {
267				t.Fatalf("page %d ToHeight=%d, want %d", i, page.ToHeight, resolvedTo)
268			}
269		}
270	
271		// Descending reads the same occurrence set the other way around,
272		// positions inside a block kept at their original values.
273		descQuery := base
274		descQuery.Order = OrderDesc
275		descPages := collectPagesResizing(t, index, descQuery, []int{2, 4, 1})
276		if got, want := flattenHits(descPages), reversed(wantHits); !reflect.DeepEqual(got, want) {
277			t.Fatalf("descending hits=%v, want %v", got, want)
278		}
279		for i, page := range descPages {
280			if page.TotalMatches != int64(len(wantHits)) || page.MatchedBlocks != wantBlocks {
281				t.Fatalf("desc page %d stats total=%d blocks=%d, want %d/%d",
282					i, page.TotalMatches, page.MatchedBlocks, len(wantHits), wantBlocks)
283			}
284		}
285	
286		// Every bucket must equal the detail query restricted to that bucket's
287		// own sub-window under the same height range and identifier set.
288		for i, bucket := range stats.Buckets {
289			bStart, bEnd := bucket.Start, bucket.End
290			sub := TxQuery{From: from, To: to, TxIDs: txIDs, TimeStart: &bStart, TimeEnd: &bEnd}
291			subHits := flattenHits(collectPages(t, index, sub))
292			if int64(len(subHits)) != bucket.TxCount {
293				t.Fatalf("bucket %d [%d,%d): details=%d, bucket TxCount=%d",
294					i, bStart, bEnd, len(subHits), bucket.TxCount)
295			}
296			subBlocks, subDistinct := summarizeHits(subHits)
297			if subBlocks != bucket.Blocks || subDistinct != bucket.DistinctTxIDs {
298				t.Fatalf("bucket %d [%d,%d): detail blocks/ids=%d/%d, bucket=%d/%d",
299					i, bStart, bEnd, subBlocks, subDistinct, bucket.Blocks, bucket.DistinctTxIDs)
300			}
301			// The sub-window details are exactly the oracle occurrences whose
302			// block time falls inside this bucket.
303			var wantSub []TxHit
304			for _, hit := range wantHits {
305				when := index.Blocks[hit.Height].Time
306				if when != nil && *when >= bStart && *when < bEnd {
307					wantSub = append(wantSub, hit)
308				}
309			}
310			if !reflect.DeepEqual(subHits, wantSub) {
311				t.Fatalf("bucket %d [%d,%d): hits=%v, want %v", i, bStart, bEnd, subHits, wantSub)
312			}
313		}
314	}
315	
316	func TestQueryTxsAndTimeStatsConsistency(t *testing.T) {
317		scenarios := []struct {
318			name       string
319			from, to   int64
320			txIDs      []string
321			start, end int64
322			step       int64
323		}{
324			// Full range, no identifier filter: duplicates inside one block,
325			// case/whitespace variants, the missing-time block, the real zero,
326			// and the end-excluded block all participate.
327			{"unfiltered", 0, 0, nil, 0, 110, 50},
328			// A repeated, reordered identifier set canonicalizes to {a, b}.
329			{"filtered set", 0, 0, []string{"b", "a", "b"}, 0, 110, 50},
330			// An empty identifier list disables the filter; a list holding only
331			// the empty string selects just the empty-identifier occurrence.
332			{"empty string filter", 0, 0, []string{""}, 0, 110, 50},
333			// Exact matching: case and surrounding whitespace matter.
334			{"case sensitive", 0, 0, []string{"A"}, 0, 110, 50},
335			{"whitespace sensitive", 0, 0, []string{" a", "a "}, 0, 110, 50},
336			// A sub-range of heights: the missing-time block at height 3 falls
337			// outside, the end-excluded block at height 6 stays excluded.
338			{"height sub-range", 4, 6, nil, 0, 110, 50},
339			// A window containing only the real zero timestamp.
340			{"zero start window", 0, 0, nil, 0, 1, 1},
341			// A legal window nothing falls into: empty details, zero buckets
342			// still covering the whole window.
343			{"no hits", 0, 0, []string{"a"}, 1000, 2000, 300},
344			// One bucket per second over a narrow slice of the chain.
345			{"fine buckets", 0, 0, nil, 94, 100, 1},
346		}
347		for _, scenario := range scenarios {
348			t.Run(scenario.name, func(t *testing.T) {
349				index := consistencyChain(t)
350				assertConsistent(t, index, scenario.from, scenario.to,
351					scenario.txIDs, scenario.start, scenario.end, scenario.step)
352			})
353		}
354	}
355	
356	func TestQueryTxsAndTimeStatsConsistencyEmptyChain(t *testing.T) {
357		// No blocks at all: the detail read is a single empty page without a
358		// cursor, and the statistics still cover the whole window with zeros.
359		index := New()
360		assertConsistent(t, index, 0, 0, nil, 0, 100, 30)
361	
362		page, err := index.QueryTxs(TxQuery{TimeStart: intptr(0), TimeEnd: intptr(100)})
363		if err != nil {
364			t.Fatal(err)
365		}
366		if len(page.Hits) != 0 || page.NextCursor != "" || page.TotalMatches != 0 || page.MatchedBlocks != 0 {
367			t.Fatalf("empty chain page=%+v, want an empty page without a cursor", page)
368		}
369	}
370	
371	func TestQueryTimeStatsWindowDistinctIsNotBucketSum(t *testing.T) {
372		// "a" occurs at t=0 (height 4, bucket [0,50)) and twice at t=100
373		// (height 1, bucket [100,110)): each bucket reports one distinct
374		// identifier, but the window-wide distinct count stays one.
375		index := consistencyChain(t)
376		stats, err := index.QueryTimeStats(TimeStatsQuery{
377			TxIDs: []string{"a"}, Start: 0, End: 110, StepSeconds: 50,
378		})
379		if err != nil {
380			t.Fatal(err)
381		}
382		var bucketSum int64
383		for _, bucket := range stats.Buckets {
384			bucketSum += bucket.DistinctTxIDs
385		}
386		if bucketSum != 2 {
387			t.Fatalf("bucket distinct sum=%d, want 2", bucketSum)
388		}
389		if stats.Totals.DistinctTxIDs != 1 {
390			t.Fatalf("window distinct=%d, want 1 (not the bucket sum)", stats.Totals.DistinctTxIDs)
391		}
392		// The paginated details agree: three occurrences, one identifier.
393		hits := flattenHits(collectPages(t, index, TxQuery{
394			TxIDs: []string{"a"}, TimeStart: intptr(0), TimeEnd: intptr(110), PageSize: 1,
395		}))
396		_, distinct := summarizeHits(hits)
397		if len(hits) != 3 || distinct != 1 || int64(len(hits)) != stats.Totals.TxCount {
398			t.Fatalf("detail hits=%v distinct=%d, stats totals=%+v", hits, distinct, stats.Totals)
399		}
400	}
