402	func TestQueryTxsAndTimeStatsFilterSetSemantics(t *testing.T) {
403		index := consistencyChain(t)
404	
405		// Order and repetitions inside the identifier set change nothing, for
406		// the statistics and for the paginated details alike.
407		base := TimeStatsQuery{TxIDs: []string{"b", "a"}, Start: 0, End: 110, StepSeconds: 50}
408		want, err := index.QueryTimeStats(base)
409		if err != nil {
410			t.Fatal(err)
411		}
412		shuffled := base
413		shuffled.TxIDs = []string{"a", "b", "a", "b"}
414		got, err := index.QueryTimeStats(shuffled)
415		if err != nil {
416			t.Fatal(err)
417		}
418		if !reflect.DeepEqual(got, want) {
419			t.Fatalf("stats with reordered set=%+v, want %+v", got, want)
420		}
421		wantHits := flattenHits(collectPages(t, index, TxQuery{
422			TxIDs: []string{"b", "a"}, TimeStart: intptr(0), TimeEnd: intptr(110),
423		}))
424		gotHits := flattenHits(collectPages(t, index, TxQuery{
425			TxIDs: []string{"a", "b", "a"}, TimeStart: intptr(0), TimeEnd: intptr(110),
426		}))
427		if !reflect.DeepEqual(gotHits, wantHits) {
428			t.Fatalf("hits with reordered set=%v, want %v", gotHits, wantHits)
429		}
430	
431		// A cursor minted under one spelling of the set continues under
432		// another spelling of the same set.
433		first, err := index.QueryTxs(TxQuery{
434			TxIDs: []string{"b", "a"}, TimeStart: intptr(0), TimeEnd: intptr(110), PageSize: 2,
435		})
436		if err != nil {
437			t.Fatal(err)
438		}
439		if first.NextCursor == "" {
440			t.Fatal("expected a continuation cursor")
441		}
442		if _, err := index.QueryTxs(TxQuery{
443			TxIDs: []string{"a", "b", "a"}, TimeStart: intptr(0), TimeEnd: intptr(110),
444			PageSize: 2, Cursor: first.NextCursor,
445		}); err != nil {
446			t.Fatalf("continuation with a respelled set failed: %v", err)
447		}
448	
449		// No filter at all is not the same as filtering for the empty string:
450		// the unrestricted read returns every occurrence, the {""} read only
451		// the empty-identifier one at height 5.
452		all, err := index.QueryTxs(TxQuery{TimeStart: intptr(0), TimeEnd: intptr(110)})
453		if err != nil {
454			t.Fatal(err)
455		}
456		emptyOnly, err := index.QueryTxs(TxQuery{
457			TxIDs: []string{""}, TimeStart: intptr(0), TimeEnd: intptr(110),
458		})
459		if err != nil {
460			t.Fatal(err)
461		}
462		if emptyOnly.TotalMatches != 1 || emptyOnly.MatchedBlocks != 1 {
463			t.Fatalf("empty-string filter total=%d blocks=%d, want 1/1",
464				emptyOnly.TotalMatches, emptyOnly.MatchedBlocks)
465		}
466		if all.TotalMatches == emptyOnly.TotalMatches {
467			t.Fatalf("unrestricted total %d must differ from the empty-string filter", all.TotalMatches)
468		}
469		emptyStats, err := index.QueryTimeStats(TimeStatsQuery{
470			TxIDs: []string{""}, Start: 0, End: 110, StepSeconds: 50,
471		})
472		if err != nil {
473			t.Fatal(err)
474		}
475		if emptyStats.Totals != (TimeTotals{TxCount: 1, DistinctTxIDs: 1, Blocks: 1}) {
476			t.Fatalf("empty-string stats totals=%+v, want 1/1/1", emptyStats.Totals)
477		}
478	}
