491		}
492		if stats.MissingTimeBlocks != 1 {
493			t.Fatalf("missing time blocks=%d, want 1", stats.MissingTimeBlocks)
494		}
495		if stats.Totals != (TimeTotals{}) {
496			t.Fatalf("totals=%+v, want all zero", stats.Totals)
497		}
