500		// block from the count as well.
501		sub, err := index.QueryTimeStats(TimeStatsQuery{From: 4, To: 6, Start: 0, End: 110, StepSeconds: 50})
502		if err != nil {
503			t.Fatal(err)
504		}
505		if sub.MissingTimeBlocks != 0 || sub.FromHeight != 4 || sub.ToHeight != 6 {
506			t.Fatalf("sub-range stats=%+v, want no missing-time blocks over heights 4..6", sub)
507		}
508	
509		// Without a time window the missing-time block's transactions are
510		// listed (and the t=110 block, excluded only by the window, joins in);
511		// with a window the missing-time block never matches.
512		noWindow := flattenHits(collectPages(t, index, TxQuery{TxIDs: []string{"b"}}))
513		if len(noWindow) != 3 || noWindow[0].Height != 1 || noWindow[1].Height != 3 || noWindow[2].Height != 6 {
514			t.Fatalf("unwindowed b hits=%v, want heights 1, 3 and 6", noWindow)
515		}
