158	// mbRestoreQualifiedHits is the MinBlocks oracle over an arbitrary chain: it
159	// counts distinct blocks per identifier under the same filter/window, keeps
160	// the identifiers reaching the threshold, and returns every surviving
161	// occurrence in height/position order, plus the whole-range statistics.
162	func mbRestoreQualifiedHits(chain []Block, ids []string, window timeWindow, minBlocks int64) (hits []TxHit, total, blocks int64) {
163		filter := make(map[string]struct{}, len(ids))
164		for _, id := range ids {
165			filter[id] = struct{}{}
166		}
167		counts := make(map[string]int64)
168		for _, block := range chain {
169			if !window.contains(block.Time) {
170				continue
171			}
172			seen := make(map[string]struct{})
173			for _, tx := range block.Txs {
174				if _, ok := filter[tx]; !ok {
175					continue
176				}
177				if _, dup := seen[tx]; dup {
178					continue
179				}
180				seen[tx] = struct{}{}
181				counts[tx]++
182			}
183		}
184		qualified := make(map[string]struct{}, len(counts))
185		for id, n := range counts {
186			if n >= minBlocks {
187				qualified[id] = struct{}{}
188			}
189		}
190		hits = []TxHit{}
191		for _, block := range chain {
192			if !window.contains(block.Time) {
193				continue
194			}
195			matched := false
196			for position, tx := range block.Txs {
197				if _, ok := filter[tx]; !ok {
198					continue
199				}
200				if _, ok := qualified[tx]; !ok {
201					continue
202				}
203				hits = append(hits, TxHit{Height: block.Height, BlockHash: block.Hash, TxID: tx, Position: position})
204				matched = true
205			}
206			if matched {
207				blocks++
208			}
209		}
210		return hits, int64(len(hits)), blocks
211	}
212	
213	// requireMbRestorePageStats checks the whole-filtered-range statistics that
214	// every page of one query must carry.
