package indexroom

import (
	"fmt"
	"testing"
)

// Temporary: the task's verbatim worked example. Times 7, missing, 0, 10;
// txs [a,a], [a], [a,b], [a].
func TestTaskWorkedExampleTmp(t *testing.T) {
	index := New()
	times := []*int64{intptr(7), nil, intptr(0), intptr(10)}
	txs := [][]string{{"a", "a"}, {"a"}, {"a", "b"}, {"a"}}
	for i := range times {
		h := int64(i + 1)
		parent := "genesis"
		if h > 1 {
			parent = fmt.Sprintf("h%d", h-1)
		}
		if err := index.Append(Block{Height: h, Hash: fmt.Sprintf("h%d", h), Parent: parent, Txs: txs[i], Time: times[i]}); err != nil {
			t.Fatal(err)
		}
	}

	// Windowed paged query, filter a over [0,10): block1 twice, block3 once.
	page, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}, TimeStart: intptr(0), TimeEnd: intptr(10), PageSize: 100})
	if err != nil {
		t.Fatal(err)
	}
	if len(page.Hits) != 3 || page.TotalMatches != 3 || page.MatchedBlocks != 2 {
		t.Fatalf("windowed page=%+v, want 3 hits/3 total/2 blocks", page)
	}
	if page.Hits[0].Height != 1 || page.Hits[0].Position != 0 ||
		page.Hits[1].Height != 1 || page.Hits[1].Position != 2 ||
		page.Hits[2].Height != 3 || page.Hits[2].Position != 0 {
		t.Fatalf("windowed hits=%+v", page.Hits)
	}

	// Stats over the same window with 5-second segments.
	stats, err := index.QueryTimeStats(TimeStatsQuery{TxIDs: []string{"a"}, Start: 0, End: 10, StepSeconds: 5})
	if err != nil {
		t.Fatal(err)
	}
	if len(stats.Buckets) != 2 {
		t.Fatalf("buckets=%+v", stats.Buckets)
	}
	if stats.Buckets[0].TxCount != 1 || stats.Buckets[1].TxCount != 2 {
		t.Fatalf("bucket counts=%d,%d, want 1,2", stats.Buckets[0].TxCount, stats.Buckets[1].TxCount)
	}
	if stats.Totals.DistinctTxIDs != 1 || stats.MissingTimeBlocks != 1 {
		t.Fatalf("totals=%+v missing=%d, want distinct 1 missing 1", stats.Totals, stats.MissingTimeBlocks)
	}

	// Time filtering off: all five a occurrences across the four blocks.
	off, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}, PageSize: 100})
	if err != nil {
		t.Fatal(err)
	}
	if off.TotalMatches != 5 || off.MatchedBlocks != 4 || len(off.Hits) != 5 {
		t.Fatalf("unwindowed page=%+v, want 5 hits/4 blocks", off)
	}
}

